/**
 * @file red_black_tree.hpp
 * @brief A dense, heavily-commented implementation of a Red-Black Tree in C++17.
 *
 * This implementation provides:
 * - Insertion with standard RB rebalancing
 * - Erasure with standard RB rebalancing
 * - Find (lower_bound, upper_bound, contains)
 * - In-order traversal
 * - Size and empty checks
 * - Height and balance verification for debugging
 * - A comprehensive test suite using a simple assertion macro
 *
 * Design notes:
 * - Nodes are allocated via a custom allocator that tracks live node count.
 * - Colors are represented as an enum with two values: RED and BLACK.
 * - The tree maintains a sentinel NIL node (black) for every leaf and as the
 *   parent of the root to simplify edge-case handling during rotations and
 *   rebalancing.
 * - All public methods are const-correct where appropriate.
 * - The tree is templated on the key type and comparator.
 */

#include <iostream>
#include <functional>
#include <memory>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <cassert>
#include <stdexcept>
#include <optional>
#include <random>
#include <chrono>

// ---------------------------------------------------------------------------
// Color enumeration
// ---------------------------------------------------------------------------

/**
 * @enum Color
 * @brief Represents the color of a red-black tree node.
 *
 * Invariant: The root is always black. The NIL sentinel is always black.
 * Every path from a node to its descendant leaves contains the same number
 * of black nodes (black-height property).
 */
enum class Color {
    RED,   ///< Red node: cannot have a red child.
    BLACK  ///< Black node: may have red or black children.
};

/**
 * @brief Stream operator for Color for debugging.
 */
inline std::ostream& operator<<(std::ostream& os, Color c) {
    return os << (c == Color::RED ? "R" : "B");
}

// ---------------------------------------------------------------------------
// Node structure
// ---------------------------------------------------------------------------

/**
 * @struct RBNode
 * @brief Internal node structure for the red-black tree.
 *
 * @tparam KeyT  The type of the key stored in the node.
 *
 * Each node stores:
 * - key: the value associated with this node
 * - color: the current color of the node
 * - parent, left, right: pointers to neighboring nodes
 *
 * Pointers to the NIL sentinel are used instead of nullptr to avoid
 * null-checks in rotation and rebalancing code.
 */
template <typename KeyT>
struct RBNode {
    KeyT key;
    Color color;
    RBNode* parent;
    RBNode* left;
    RBNode* right;

    /**
     * @brief Construct a new RBNode.
     * @param k The key to store.
     * @param c The initial color (defaults to RED for new insertions).
     * @param p Parent pointer (defaults to nullptr, set during insertion).
     */
    explicit RBNode(const KeyT& k, Color c = Color::RED, RBNode* p = nullptr)
        : key(k), color(c), parent(p), left(nullptr), right(nullptr) {}

    /**
     * @brief Construct a new RBNode with move semantics for the key.
     */
    explicit RBNode(KeyT&& k, Color c = Color::RED, RBNode* p = nullptr)
        : key(std::move(k)), color(c), parent(p), left(nullptr), right(nullptr) {}
};

// ---------------------------------------------------------------------------
// Allocator for RBNodes
// ---------------------------------------------------------------------------

/**
 * @struct RBNodeAllocator
 * @brief Tracks the number of live nodes for size queries.
 *
 * This is a simple counter-based allocator. In production, one might use
 * a pool allocator or std::pmr. Here we keep it simple and thread-unsafe
 * (the tree itself is not thread-safe).
 */
template <typename KeyT>
struct RBNodeAllocator {
    size_t live_count = 0;

    RBNode<KeyT>* allocate() {
        ++live_count;
        return new RBNode<KeyT>(KeyT{}, Color::BLACK, nullptr);
    }

    void deallocate(RBNode<KeyT>* node) {
        if (node && node != nullptr) {
            --live_count;
            delete node;
        }
    }
};

